//! The event JSON API end to end through the router, without a network:
//! an in-memory repository with the same optimistic locking as SQL and,
//! for this tenant-scoped resource, real bearer tokens resolved by the
//! generated `BearerTenantAccess` from in-memory session and membership
//! stores. Every response is also checked against the OpenAPI document.
//! Generated by `forge generate resource` (and `forge generate scaffold`).

use std::error::Error;
use std::sync::{Arc, Mutex, MutexGuard};

use app::adapters::http::api_access::{ApiTenantAccess, BearerTenantAccess, DenyAll};
use app::application::ports::event_repository::{EventPage, EventRepository, EventStoreError};
use app::application::use_cases::events::{EventService, READ_PERMISSION, WRITE_PERMISSION};
use app::domain::entities::event::{Event, EventId};
use async_trait::async_trait;
use forge::auth::{Session, SessionBearerToken, UnixTimestamp};
use forge::core::Version;
use forge::http::{HeaderMap, HeaderValue, Method, Request, Response, Router, StatusCode, header};
use forge::security::Permission;
use forge::security::{PrincipalId, RbacPolicy, Role};
use forge::tenancy::testing::{MemoryBearerSessionStore, MemoryMembershipStore};
use forge::tenancy::{
    BearerSession, BearerSessionStore as _, Membership, MembershipStore as _, TenantContext,
    TenantId,
};
use serde_json::{Value, json};

type TestResult = Result<(), Box<dyn Error>>;

/// A body every rule accepts.
const VALID: &str = r#"{"name": "Example name", "notes": "Example notes", "starts_at": "2026-01-02T03:04:05Z", "ends_at": "2026-01-02T03:04:05Z", "capacity": 42, "attendees": 42, "public": true, "featured": true, "venue": "67e55044-10b1-426f-9247-bb680e5fe0c8", "organizer": "67e55044-10b1-426f-9247-bb680e5fe0c8"}"#;
/// A body with one value that breaks a rule, and the code of its refusal.
const INVALID: &str = r#"{"name": " ", "notes": "Example notes", "starts_at": "2026-01-02T03:04:05Z", "ends_at": "2026-01-02T03:04:05Z", "capacity": 42, "attendees": 42, "public": true, "featured": true, "venue": "67e55044-10b1-426f-9247-bb680e5fe0c8", "organizer": "67e55044-10b1-426f-9247-bb680e5fe0c8"}"#;
const INVALID_CODE: &str = "validation_failed";

/// Events in memory, with the same optimistic locking as the SQL
/// repository.
#[derive(Default)]
struct InMemoryEvents {
    rows: Mutex<Vec<(TenantId, Event)>>,
}

impl InMemoryEvents {
    fn rows(&self) -> Result<MutexGuard<'_, Vec<(TenantId, Event)>>, EventStoreError> {
        self.rows.lock().map_err(|_| EventStoreError::Corrupt)
    }
}

#[async_trait]
impl EventRepository for InMemoryEvents {
    async fn find(
        &self,
        context: &TenantContext,
        id: EventId,
    ) -> Result<Option<Event>, EventStoreError> {
        Ok(self
            .rows()?
            .iter()
            .filter(|(tenant, _)| *tenant == context.tenant_id())
            .map(|(_, stored)| stored)
            .find(|stored| stored.id() == id)
            .cloned())
    }

    async fn page(
        &self,
        context: &TenantContext,
        after: Option<EventId>,
        limit: u16,
    ) -> Result<EventPage, EventStoreError> {
        let mut events: Vec<Event> = self
            .rows()?
            .iter()
            .filter(|(tenant, _)| *tenant == context.tenant_id())
            .map(|(_, stored)| stored)
            .filter(|stored| after.is_none_or(|after| stored.id() > after))
            .cloned()
            .collect();
        events.sort_by_key(Event::id);
        let next = if events.len() > usize::from(limit) {
            events.truncate(usize::from(limit));
            events.last().map(Event::id)
        } else {
            None
        };
        Ok(EventPage { events, next })
    }

    async fn insert(&self, context: &TenantContext, event: &Event) -> Result<(), EventStoreError> {
        self.rows()?.push((context.tenant_id(), event.clone()));
        Ok(())
    }

    async fn update(
        &self,
        context: &TenantContext,
        event: &Event,
    ) -> Result<Version, EventStoreError> {
        let next = event
            .version()
            .next()
            .map_err(|_| EventStoreError::Conflict)?;
        let mut rows = self.rows()?;
        let stored = rows
            .iter_mut()
            .filter(|(tenant, _)| *tenant == context.tenant_id())
            .map(|(_, stored)| stored)
            .find(|stored| stored.id() == event.id() && stored.version() == event.version())
            .ok_or(EventStoreError::Conflict)?;
        *stored = event.clone().with_version(next);
        Ok(next)
    }

    async fn delete(
        &self,
        context: &TenantContext,
        id: EventId,
        expected: Version,
    ) -> Result<(), EventStoreError> {
        let mut rows = self.rows()?;
        let before = rows.len();
        rows.retain(|(tenant, stored)| {
            !(*tenant == context.tenant_id() && stored.id() == id && stored.version() == expected)
        });
        if rows.len() == before {
            Err(EventStoreError::Conflict)
        } else {
            Ok(())
        }
    }
}

/// The router with only the event API, checked against its OpenAPI
/// document.
struct Harness {
    router: Router,
    sessions: Arc<MemoryBearerSessionStore>,
    memberships: Arc<MemoryMembershipStore>,
}

impl Harness {
    /// The API behind `BearerTenantAccess`, whose policy grants `owner`
    /// read and write and `viewer` read only.
    fn new() -> Result<Self, Box<dyn Error>> {
        let sessions = Arc::new(MemoryBearerSessionStore::default());
        let memberships = Arc::new(MemoryMembershipStore::default());
        let mut policy = RbacPolicy::new();
        let owner = Role::new("owner")?;
        policy.allow(owner.clone(), Permission::new(READ_PERMISSION)?);
        policy.allow(owner, Permission::new(WRITE_PERMISSION)?);
        policy.allow(Role::new("viewer")?, Permission::new(READ_PERMISSION)?);
        let access = BearerTenantAccess::new(sessions.clone(), memberships.clone(), policy);
        let mut harness = Self::with_access(Arc::new(access))?;
        harness.sessions = sessions;
        harness.memberships = memberships;
        Ok(harness)
    }

    fn with_access(access: Arc<dyn ApiTenantAccess>) -> Result<Self, Box<dyn Error>> {
        let mut router = Router::new();
        app::adapters::http::events_api::routes(
            &mut router,
            EventService::new(Arc::new(InMemoryEvents::default())),
            access,
        )?;
        let document = router.openapi(&forge::openapi::Info::new("app", "0.0.0"))?;
        router.layer(forge::openapi::CheckResponses::new(document, |failure| {
            panic!("{failure}")
        }));
        Ok(Self {
            router,
            sessions: Arc::new(MemoryBearerSessionStore::default()),
            memberships: Arc::new(MemoryMembershipStore::default()),
        })
    }

    /// A new principal with `role` in `tenant` and a live bearer token for
    /// it, as `POST /auth/login` issues: the `Authorization` value.
    async fn token(&self, tenant: TenantId, role: &str) -> Result<String, Box<dyn Error>> {
        let principal = PrincipalId::new();
        self.memberships
            .upsert(&Membership::active(
                tenant,
                principal,
                vec![Role::new(role)?],
            ))
            .await?;
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_secs();
        let session = Session::new(
            principal,
            UnixTimestamp::from_secs(now - 60),
            UnixTimestamp::from_secs(now + 3_600),
        )?;
        let token = SessionBearerToken::generate()?;
        self.sessions
            .insert(&BearerSession::new(session, tenant), &token.digest())
            .await?;
        Ok(format!("Bearer {}", token.expose()))
    }

    async fn send(
        &self,
        method: Method,
        path: &str,
        authorization: Option<&str>,
        body: Option<&str>,
    ) -> Result<Response, Box<dyn Error>> {
        let mut headers = HeaderMap::new();
        if let Some(authorization) = authorization {
            headers.insert(header::AUTHORIZATION, HeaderValue::from_str(authorization)?);
        }
        if body.is_some() {
            headers.insert(
                header::CONTENT_TYPE,
                HeaderValue::from_static("application/json"),
            );
        }
        let request = Request::new_for_test(
            method,
            path.parse()?,
            headers,
            body.unwrap_or_default().to_owned().into(),
            "127.0.0.1:4000".parse()?,
            forge::core::Id::<Request>::new().into_uuid(),
        );
        Ok(self.router.dispatch(request).await)
    }
}

fn json_body(response: &Response) -> Value {
    serde_json::from_slice(response.body()).unwrap_or(Value::Null)
}

fn id_of(response: &Response) -> Result<String, Box<dyn Error>> {
    Ok(json_body(response)["id"]
        .as_str()
        .ok_or("the response has an id")?
        .to_owned())
}

#[tokio::test]
async fn create_show_list_update_and_delete() -> TestResult {
    let harness = Harness::new()?;
    let token = harness.token(TenantId::new(), "owner").await?;
    let token = Some(token.as_str());

    let created = harness
        .send(Method::POST, "/v1/events", token, Some(VALID))
        .await?;
    assert_eq!(
        created.status(),
        StatusCode::CREATED,
        "{:?}",
        json_body(&created)
    );
    let id = id_of(&created)?;
    let path = format!("/v1/events/{id}");
    assert_eq!(
        created
            .headers()
            .get(header::LOCATION)
            .and_then(|value| value.to_str().ok()),
        Some(path.as_str())
    );
    assert_eq!(json_body(&created)["version"], 1);
    assert_eq!(json_body(&created)["name"], json!("Example name"));

    let shown = harness.send(Method::GET, &path, token, None).await?;
    assert_eq!(shown.status(), StatusCode::OK);
    assert_eq!(json_body(&shown), json_body(&created));

    let listed = harness.send(Method::GET, "/v1/events", token, None).await?;
    assert_eq!(listed.status(), StatusCode::OK);
    assert_eq!(json_body(&listed)["items"][0]["id"], json!(id));
    assert_eq!(json_body(&listed)["next_cursor"], Value::Null);

    let changes = json!({"version": 1, "name": "Changed"}).to_string();
    let updated = harness
        .send(Method::PATCH, &path, token, Some(&changes))
        .await?;
    assert_eq!(
        updated.status(),
        StatusCode::OK,
        "{:?}",
        json_body(&updated)
    );
    assert_eq!(json_body(&updated)["version"], 2);
    assert_eq!(json_body(&updated)["name"], json!("Changed"));

    let deleted = harness
        .send(Method::DELETE, &format!("{path}?version=2"), token, None)
        .await?;
    assert_eq!(deleted.status(), StatusCode::NO_CONTENT);
    let gone = harness.send(Method::GET, &path, token, None).await?;
    assert_eq!(gone.status(), StatusCode::NOT_FOUND);
    assert_eq!(json_body(&gone)["code"], "event_not_found");
    Ok(())
}

#[tokio::test]
async fn invalid_values_and_bodies_are_unprocessable() -> TestResult {
    let harness = Harness::new()?;
    let token = harness.token(TenantId::new(), "owner").await?;
    let token = Some(token.as_str());
    let invalid = harness
        .send(Method::POST, "/v1/events", token, Some(INVALID))
        .await?;
    assert_eq!(invalid.status(), StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(json_body(&invalid)["code"], INVALID_CODE);
    for body in ["{}", "not json", r#"{"unknown": 1}"#] {
        let refused = harness
            .send(Method::POST, "/v1/events", token, Some(body))
            .await?;
        assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY, "{body}");
        assert_eq!(json_body(&refused)["code"], "invalid_json", "{body}");
    }
    let listed = harness.send(Method::GET, "/v1/events", token, None).await?;
    assert_eq!(json_body(&listed)["items"], json!([]), "nothing was stored");
    Ok(())
}

#[tokio::test]
async fn a_stale_version_conflicts_and_unknown_ids_are_not_found() -> TestResult {
    let harness = Harness::new()?;
    let token = harness.token(TenantId::new(), "owner").await?;
    let token = Some(token.as_str());
    let created = harness
        .send(Method::POST, "/v1/events", token, Some(VALID))
        .await?;
    let path = format!("/v1/events/{}", id_of(&created)?);
    let stale = json!({"version": 7}).to_string();
    let conflict = harness
        .send(Method::PATCH, &path, token, Some(&stale))
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);
    assert_eq!(json_body(&conflict)["code"], "event_conflict");
    let conflict = harness
        .send(Method::DELETE, &format!("{path}?version=7"), token, None)
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);

    let unknown = format!("/v1/events/{}", EventId::new());
    for method in [Method::GET, Method::PATCH] {
        let body = (method == Method::PATCH).then_some(r#"{"version": 1}"#);
        let missing = harness.send(method, &unknown, token, body).await?;
        assert_eq!(missing.status(), StatusCode::NOT_FOUND);
    }
    let malformed = harness
        .send(Method::GET, "/v1/events/not-an-id", token, None)
        .await?;
    assert_eq!(malformed.status(), StatusCode::BAD_REQUEST);
    assert_eq!(json_body(&malformed)["code"], "invalid_id");
    Ok(())
}

/// No `Authorization` header, a malformed one, an unknown token or a token
/// sent as a cookie: `401` with the bearer challenge, before anything is
/// read or stored.
#[tokio::test]
async fn a_request_without_a_valid_token_is_unauthorized() -> TestResult {
    let harness = Harness::new()?;
    let unknown = format!("Bearer {}", "ab".repeat(32));
    for (authorization, code) in [
        (None, "credentials_required"),
        (Some("Basic dXNlcjpwYXNz"), "credentials_invalid"),
        (Some("Bearer not-a-token"), "credentials_invalid"),
        (Some(unknown.as_str()), "credentials_invalid"),
    ] {
        for (method, body) in [(Method::GET, None), (Method::POST, Some(VALID))] {
            let response = harness
                .send(method, "/v1/events", authorization, body)
                .await?;
            assert_eq!(
                response.status(),
                StatusCode::UNAUTHORIZED,
                "{authorization:?}"
            );
            assert_eq!(json_body(&response)["code"], code);
            assert_eq!(
                response
                    .headers()
                    .get(header::WWW_AUTHENTICATE)
                    .and_then(|value| value.to_str().ok()),
                Some("Bearer realm=\"forge\"")
            );
        }
    }
    Ok(())
}

/// A role granted only `events:read` reads but cannot write, and a
/// token without a membership in its tenant can do neither.
#[tokio::test]
async fn a_role_without_the_permission_is_forbidden() -> TestResult {
    let harness = Harness::new()?;
    let tenant = TenantId::new();
    let viewer = harness.token(tenant, "viewer").await?;
    let listed = harness
        .send(Method::GET, "/v1/events", Some(&viewer), None)
        .await?;
    assert_eq!(listed.status(), StatusCode::OK);
    let refused = harness
        .send(Method::POST, "/v1/events", Some(&viewer), Some(VALID))
        .await?;
    assert_eq!(refused.status(), StatusCode::FORBIDDEN);
    assert_eq!(json_body(&refused)["code"], "permission_denied");

    let stranger = harness.token(tenant, "guest").await?;
    let refused = harness
        .send(Method::GET, "/v1/events", Some(&stranger), None)
        .await?;
    assert_eq!(refused.status(), StatusCode::FORBIDDEN);
    Ok(())
}

/// A token works only in the tenant it was issued for: another tenant's
/// events are neither listed nor found, changed or deleted.
#[tokio::test]
async fn another_tenants_rows_are_invisible() -> TestResult {
    let harness = Harness::new()?;
    let ours = harness.token(TenantId::new(), "owner").await?;
    let theirs = harness.token(TenantId::new(), "owner").await?;
    let created = harness
        .send(Method::POST, "/v1/events", Some(&ours), Some(VALID))
        .await?;
    assert_eq!(created.status(), StatusCode::CREATED);
    let path = format!("/v1/events/{}", id_of(&created)?);

    let listed = harness
        .send(Method::GET, "/v1/events", Some(&theirs), None)
        .await?;
    assert_eq!(json_body(&listed)["items"], json!([]));
    let changes = json!({"version": 1}).to_string();
    for (method, path, body) in [
        (Method::GET, path.clone(), None),
        (Method::PATCH, path.clone(), Some(changes.as_str())),
        (Method::DELETE, format!("{path}?version=1"), None),
    ] {
        let response = harness.send(method, &path, Some(&theirs), body).await?;
        assert_eq!(response.status(), StatusCode::NOT_FOUND, "{path}");
    }
    let still = harness.send(Method::GET, &path, Some(&ours), None).await?;
    assert_eq!(still.status(), StatusCode::OK);
    Ok(())
}

/// The use cases check the grant again: a context authorized for another
/// permission is refused even if a policy let the request through.
#[tokio::test]
async fn the_use_cases_refuse_a_context_granted_for_another_permission() -> TestResult {
    let tenant = TenantId::new();
    let principal = PrincipalId::new();
    let authenticated = Session::new(
        principal,
        UnixTimestamp::from_secs(10),
        UnixTimestamp::from_secs(20),
    )?
    .authenticate(UnixTimestamp::from_secs(11))?;
    let role = Role::new("viewer")?;
    let read = Permission::new(READ_PERMISSION)?;
    let mut policy = RbacPolicy::new();
    policy.allow(role.clone(), read.clone());
    let context = TenantContext::authorize(
        authenticated,
        &Membership::active(tenant, principal, vec![role]),
        &policy,
        &read,
    )?;
    let service = EventService::new(Arc::new(InMemoryEvents::default()));
    let refused = service
        .delete(&context, EventId::new(), Version::INITIAL)
        .await;
    assert!(refused.is_err());
    Ok(())
}

#[tokio::test]
async fn the_generated_deny_all_default_refuses_every_route() -> TestResult {
    let harness = Harness::with_access(Arc::new(DenyAll))?;
    let member = format!("/v1/events/{}", EventId::new());
    let changes = json!({"version": 1}).to_string();
    for (method, path, body) in [
        (Method::GET, "/v1/events".to_owned(), None),
        (Method::POST, "/v1/events".to_owned(), Some(VALID)),
        (Method::GET, member.clone(), None),
        (Method::PATCH, member.clone(), Some(changes.as_str())),
        (Method::DELETE, format!("{member}?version=1"), None),
    ] {
        let response = harness.send(method, &path, None, body).await?;
        assert_eq!(response.status(), StatusCode::FORBIDDEN, "{path}");
    }
    Ok(())
}
